def sheet(name,description):
 s=wb.add_worksheet(name); sheets.append((name,description)); s.hide_gridlines(2); s.set_default_row(34); s.set_column('A:A',24); s.set_column('B:N',19); s.freeze_panes(1,0); s.set_landscape(); s.set_paper(9); s.fit_to_pages(1,0); s.set_margins(.3,.3,.4,.4); s.set_footer('&LУчебная работа • Электронные таблицы&RСтраница &P'); return s
def text(s,cell,val,style='plain'): s.write(cell,val,fmt[style])
def f(s,cell,formula,value,style='calc'): s.write_formula(cell,formula,fmt[style],value)
def row(s,r,values,style='input'):
 for c,v in enumerate(values): s.write(r-1,c,v,fmt[style])
def heads(s,r,values): row(s,r,values,'head'); s.set_row(r-1,58)
def memo(s,r,msg,end=7): s.merge_range(r-1,0,r, end,msg,note); s.set_row(r-1,32)
def result(title_,sheet_,formula_,value_,details=''): records.append((title_,sheet_,formula_,str(value_),details))
def chart(s,typ,title_,cats,series,anchor):
 ch=wb.add_chart({'type':typ});
 for name,col,start,end in series:
  ch.add_series({'name':name,'categories':[s.name,cats[1]-1,cats[0],cats[2]-1,cats[0]],'values':[s.name,start-1,col,end-1,col], 'data_labels':{'value':typ!='pie','percentage':typ=='pie'}, **({'marker':{'type':'circle'}} if typ=='line' else {})})
 ch.set_title({'name':title_}); ch.set_legend({'position':'bottom'}); ch.set_style(10); ch.set_size({'width':620,'height':330}); s.insert_chart(anchor,ch)
def serial(d): return (d-datetime(1899,12,30)).days
def workday(d,n,holidays=()):
 while n:
  d+=timedelta(days=1)
  if d.weekday()<5 and d not in holidays:n-=1
 return d
